function buildId(processId, productId, workOrderProcessId) {
    return processId ? processId : "_" + productId + "_" + workOrderProcessId;
}

function getBomRequirements(bom, quantity, components, total) {
    const r = {}
    for (let i = 0; i < bom.length; i++) {
        let b = bom[i];
        const p = buildId(b.componentProductStrategyProcessId, b.componentProduct.id, b.workOrderProcessId);
        if (b.consumptionMode.actualUsage) {
            r[p] ? r[p] += components[p]?.usage * (quantity / total) : r[p] = components[p]?.usage * (quantity / total);
        } else {
            r[p] ? r[p] += (b.standardUsage * quantity) : r[p] = (b.standardUsage * quantity);
        }
    }
    return r;
}
function buildOutput(qty, pack, bom, partial, components) {
    console.log(qty)
    let quantity = qty;
    const output = [];
    if (partial.length) {
        for (let i = 0; i < partial.length; i++) {
            const p = partial[i];
            if ((pack - p.qty) > quantity) {
                output.push({ qty: quantity, rqd: getBomRequirements(bom, quantity, components, qty), inv: [], partial: p });
                return output;
            } else {
                if (pack - p.qty > 0) {
                    quantity -= (pack - p.qty);
                    output.push({ qty: pack - p.qty, rqd: getBomRequirements(bom, pack - p.qty, components, qty), inv: [], partial: p });
                }
            }
        }
    }
    /// standard pack causing issues
    const standard = getBomRequirements(bom, pack, components, qty);
    for (let i = 0; i < Math.trunc(quantity / pack); i++) { output.push({ qty: pack, rqd: { ...standard }, inv: [] }) };
    if (quantity % pack) output.push({ qty: quantity % pack, rqd: getBomRequirements(bom, quantity % pack, components, qty), inv: [] });
    return output;
}

function getMaterialRequirements(productionMaterial, quantity, pack, bom, partial, wip, components) {
    const comp = {};
    const keys = Object.keys(components);
    for (let i = 0; i < keys?.length ?? 0; i++) {
        const c = components[keys[i]];
        comp[buildId(c.productStrategyProcessId, c.productId, c.workOrderProcessId)] = c;
    }
    const material = [...productionMaterial];
    const output = buildOutput(quantity, pack || quantity, bom, partial, comp);
    for (let i = 0; i < bom.length; i++) {
        const b = bom[i];
        const p = buildId(b.componentProductStrategyProcessId, b.componentProduct.id, b.workOrderProcessId);

        for (let ii = 0; ii < output.length; ii++) {
            for (let iii = 0; iii < material.length; iii++) {
                const m = material[iii];
                if (!m.originalQuantity) m.originalQuantity = m.inventory.quantity.value;
                if (m.inventory.quantity.value > 0 && (m.inventory.productStrategyProcessId === b.componentProductStrategyProcessId || (b.componentProduct.id === m.inventory.productId && m.inventory.workOrderProcessId && m.inventory.workOrderProcessId === wip))) {
                    if (m) {
                        const r = Math.trunc(output[ii].rqd[p] * 100000000) / 100000000; // Deal with floating point errors - MAX_VALUE in JS is ~ 1.79e+308 (with essentially no decimal precision), but precision start dropping off around 15 digits
                        if (r) {
                            if (m.inventory.quantity.value >= r) {
                                output[ii].inv.push({ id: m.inventory.id, qty: r });
                                m.inventory.quantity.value -= r;
                                output[ii].rqd[p] = 0;
                            } else {
                                output[ii].inv.push({ id: m.inventory.id, qty: m.inventory.quantity.value });
                                output[ii].rqd[p] -= m.inventory.quantity.value;
                                m.inventory.quantity.value = 0;
                            }
                        }
                    }
                }
            }
        }
    }
    let result = true;
    for (let i = 0; i < output.length; i++) {
        Object.values(output[i].rqd).forEach(v => { if (v > 0) result = false });
        if (!result) break;
    }
    let reqd = {};
    if (!result) {
        reqd = bom.reduce((acc, b) => {
            const p = b.componentProductStrategyProcessId ? b.componentProductStrategyProcessId : "_" + b.componentProduct.id + "_" + b.workOrderProcessId;
            acc[p] = {
                "code": b.componentProduct.code,
                "qty": 0
            };
            return acc;
        }, {});
        for (let i = 0; i < output.length; i++) {
            const o = output[i];
            Object.keys(o.rqd).forEach(k => {
                reqd[k].qty += o.rqd[k];
            })
        }
    }

    return {
        material,
        output,
        result,
        reqd
    }
}

const outputs = $state.context.LOCAL.outputs;
const results = [];
let material = [...$state.context.LOCAL.material];

for (let i = 0; i < outputs.length; i++) {
    const output = outputs[i].output;
    const result = getMaterialRequirements(
        material,
        $state.context.LOCAL.quantity * output.unitPerCycle,
        null, // standard pack should be defined per output
        output.standardBoms.edges.map(b => b.node),
        $state.context.LOCAL?.partial?.map(p => ({ id: p.id, qty: p.quantity.value })) ?? [],
        $state.context.LOCAL.wip?.id ?? "!!!",
        $state.context.REQUEST.DATA?.components ?? {}
    );
    results.push({id:output.id,result});
    material = [...result.material];
}

return results;

(

  $L := $state.context.LOCAL;
  $R := $state.context.REQUEST.DATA;
  $q := 
    (
      $state.context.LOCAL.dist.workOrderProcess.transferSerial
        or
      $state.context.LOCAL.card.rack.productStrategyProcess.transferSerial
    )
  ? 
   (
     $isNilOrEmpty($R.serials) 
     ? $coalesce([$R.quantity,$L.output.standardPackQuantity,serialMaterial.edges[0].node.inventory.quantity.value])
     : $sum(serialMaterial.edges.node.inventory.quantity.value)
   )
  : $coalesce([$R.quantity,$L.output.standardPackQuantity,serialMaterial.edges[0].node.inventory.quantity.value]);
  $sp := $coalesce([
        serialMaterial.edges[0].node.inventory.quantity.value,
        $L.output.standardPackQuantity,
        $R.quantity
  ]);
  $n := $q/$coalesce([$sp,1]);


  {
    "LOCAL": {

      "serialMaterial": [serialMaterial.edges#$i[$i<$n].node],
      "standardPack": $sp,
      "quantity": $q,
      "material": [material.edges.node]~>|$|{
        "originalQuantity": inventory.quantity.value
      }|
    }
  }

)

/* Watch out for enquads (hidden unicode for formatting) */

{
  "SUCCESS": false,
  "MESSAGE": "Failed to Produce. Additional Requirements for Quantity " 
    & $state.context.REQUEST.DATA.quantity
    & ":                    "
    & $join(
      $each(reqd, function($v, $k) {
        "     Product: " & $v.code & ", Quantity: " & $v.qty & "                                            "
      })," "
    )
}

function buildTrx(material, output, serials, partials) {
    const inventory = {};
    for (let i = 0; i < material.length; i++) {
        const m = material[i];
        if (m.inventory.quantity.value === m.originalQuantity) continue;
        inventory[m.inventory.id] = {
            ...m.inventory,
            originalQuantity: m.originalQuantity,
            materialId: m.id
        }
    }
    const production = [];
    if (serials.length) {
        for (let i = 0; i < output.length; i++) {
            const serial = serials.shift();
            const o = output[i];
            production.push({
                serial: serial.inventory,
                partial: null,
                quantity: o.qty,
                trx: o.inv.map(inv => ({
                    inventory: { ...inventory[inv.id], quantity: { value: inv.qty, unitId: inventory[inv.id].quantity.unitId } }

                })
                )
            })

        }

    }
    else {
        for (let i = 0; i < output.length; i++) {
            const o = output[i];

            production.push({
                serial: null,
                partial: o.partial && partials?.length ? partials.find(p => p.id === o.partial.id) : null,
                quantity: o.qty,
                trx: o.inv.map(inv => ({

                    inventory: { ...inventory[inv.id], quantity: { value: inv.qty, unitId: inventory[inv.id].quantity.unitId } }
                })
                )
            })

        }
    }
    return { inventory, production }
}
const results = [];
for (const i of $) {
    const { inventory, production } = buildTrx(i.result.material, i.result.output, $state.context.REQUEST.DATA?.productionTypeId === 'Production (Transfer Serial)' ? [...$state.context.LOCAL.serialMaterial] : [], $state.context.LOCAL?.partial?.length > 0 ? [...$state.context.LOCAL.partial] : []);
    results.push({ inventory, production,id:i.id});
}
return results;

