    }
  }];

  $updateSerial := $ts ? [] : [production[$not($isNilOrEmpty(serial))].serial.{
    "update": {
      "grossWeight": $coalesce([$wop.unitWeight,$psp.unitWeight,0]) * %.quantity,  /*plus packaging? */
      "netWeight": $coalesce([$wop.unitWeight,$psp.unitWeight,0]) * %.quantity,
      "tareWeight": 0, /* packaging * quantity???? $coalesce([$wop.unitWeight,0]) * quantity, */
      "theoreticalWeight": $coalesce([$wop.unitWeight,$psp.unitWeight,0]) * %.quantity, /*=gross??*/
      "active": $R.OCustomer-DON.scrap ? false : true,
      "inventoryStatusId": $R.OCustomer-DON.scrap ? "Scrap" : $R.OCustomer-DON.suspect ? "Suspect" : "OK",
