            parallelPositions
            distributions {
              total
            }
          }
          leadingDistribution {
            id
            output: productionSetupOutputs {
              edges {
                node {
                  id
                  boms: setupBoms(
                    where: {
                      consumptionMode: { noConsumption: { _eq: false } }
                      bomTypeId: { _eq: "Product" }
                    }
                  ) {
                    edges {
                      node {
                        standardUsage
                        minimumUsage
                        maximumUsage
                        componentProductStrategyProcessId
                        componentProduct {
                          id
                          code
                        }
                        componentPackagingMaterialId
                        componentProductStrategyId
                        bomTypeId
                        workOrderProcessId
                        consumptionMode {
                          intraprocess
                          noConsumption
                          transferSerial
                          requireSerial
                          standardUsage
                          validateOnProduction
                          actualUsage
                        }
                      }
                    }
                  }
                }
              }
            }
          }
          balanceQuantity
          standardRate
          laborUsage
          machineUsage
          materialUsage
          producedQuantity
          requiredQuantity
          scrappedQuantity
          setupRate
          leadingProduct
          workOrderProcessDistributionStatusId
          workOrder {
            id
            workOrderProcesses {
              edges {
                node {
                  id
                  order
                  final
                }
              }
            }
          }
          workOrderProcess {
            id
            code
            final
            productStrategy {
              id
              productId
              inventoryUnitId
            }
            wip
            finishedGood
            transferSerial
            unitWeight
            weightUnitId
            lotControl {
              beginProcessId
              autoLotNumber
