              qualitySubjectLists {
                edges {
                  node {
                    id
                    interval {
                      id
                    }
                  }
                }
              }
            }
            productionType {
              id
              byProduct
              cell
              disassembly
              outside
              packaging
              production
              rework
            }
          }
          productionHistories(
            where: $wherePH
            orderBy: { field: occurAt, direction: desc }
            first: 1
          ) {
            edges {
              node {
                occurAt
              }
            }
          }
        }
        standardBoms: setupBoms(
          where: {
            _and: [{ consumptionMode: { transferSerial: { _eq: false } } }]
          }
        ) {
          edges {
            node {
              standardUsage
              minimumUsage
              maximumUsage
              componentProductStrategyProcessId
              componentProduct {
                id
                code
              }
              componentPackagingMaterialId
              componentProductStrategyId
              bomTypeId
              standardPackQuantity
              workOrderProcessId
              consumptionMode {
                intraprocess
                transferSerial
                standardUsage
                validateOnProduction
                requireSerial
                noConsumption
                actualUsage
              }
            }
          }
        }
        serialBoms: setupBoms(
          where: {
            _or: [{ consumptionMode: { transferSerial: { _eq: true } } }]
          }
        ) {
          edges {
            node {
              standardUsage
              componentProductStrategyProcessId
              componentProduct {
                id
                code
              }
              componentPackagingMaterialId
              componentProductStrategyId
              bomTypeId
              standardPackQuantity
              workOrderProcessId
              consumptionMode {
                intraprocess
                transferSerial
                standardUsage
                validateOnProduction
                requireSerial
                noConsumption
                actualUsage
              }
            }
          }
        }
        updatedAt
      }
    }
  }
  partial: inventory(where: $whereP) {
