// Utility function to build a unique identifier for components
function buildId(processId, productId, workOrderProcessId) {
    return processId ? processId : `_${productId}_${workOrderProcessId}`;
}

// Function to calculate BOM (Bill of Materials) requirements based on quantity
function getBomRequirements(bom, quantity, components, total) {
    const requirements = {};

    bom.forEach((b) => {
        const componentId = buildId(b.componentProductStrategyProcessId, b.componentProduct.id, b.workOrderProcessId);

        if (b.consumptionMode.actualUsage) {
            // Calculate using actual usage
            requirements[componentId] = (requirements[componentId] || 0) +
                (components[componentId]?.usage || 0) * (quantity / total);
        } else {
            // Calculate using standard usage
            requirements[componentId] = (requirements[componentId] || 0) +
                (b.standardUsage * quantity);
        }
    });

    return requirements;
}

// Function to generate output batches with BOM requirements
function buildOutput(quantity, packSize, bom, partial, components) {
    const output = [];

    // Process partial batches
    partial.forEach((p) => {
        const remaining = packSize - p.qty;
        if (remaining > quantity) {
            output.push({
                qty: quantity,
                rqd: getBomRequirements(bom, quantity, components, quantity),
                inv: [],
                partial: p
            });
            quantity = 0;
        } else {
            quantity -= remaining;
            output.push({
                qty: remaining,
                rqd: getBomRequirements(bom, remaining, components, quantity),
                inv: [],
                partial: p
            });
        }
    });

    // Generate full and leftover batches
    const standardRequirements = getBomRequirements(bom, packSize, components, quantity);
    for (let i = 0; i < Math.floor(quantity / packSize); i++) {
        output.push({ qty: packSize, rqd: { ...standardRequirements }, inv: [] });
    }

    if (quantity % packSize) {
        output.push({
            qty: quantity % packSize,
            rqd: getBomRequirements(bom, quantity % packSize, components, quantity),
            inv: []
        });
    }

    return output;
}

// Main function to calculate material requirements
function getMaterialRequirements(productionMaterial, quantity, packSize, bom, partial, wip, components) {
    const comp = {};

    // Build a components map for quick lookup
    Object.keys(components).forEach((key) => {
        const c = components[key];
        comp[buildId(c.productStrategyProcessId, c.productId, c.workOrderProcessId)] = c;
    });

    const material = [...productionMaterial];
    const output = buildOutput(quantity, packSize, bom, partial, comp);

    // Match materials with BOM requirements
    bom.forEach((b) => {
        const componentId = buildId(b.componentProductStrategyProcessId, b.componentProduct.id, b.workOrderProcessId);

        output.forEach((batch) => {
            material.forEach((m) => {
                if (!m.originalQuantity) m.originalQuantity = m.inventory.quantity.value;

                if (m.inventory.quantity.value > 0 &&
                    (m.inventory.productStrategyProcessId === b.componentProductStrategyProcessId ||
                     m.inventory.productId === b.componentProduct.id && m.inventory.productStrategyProcess.final ||
                        (b.componentProduct.id === m.inventory.productId && m.inventory.workOrderProcessId === wip))) {

                    const requiredQty = Math.trunc(batch.rqd[componentId] * 1e8) / 1e8;
                    if (requiredQty) {
                        if (m.inventory.quantity.value >= requiredQty) {
                            batch.inv.push({ id: m.inventory.id, qty: requiredQty });
                            m.inventory.quantity.value -= requiredQty;
                            batch.rqd[componentId] = 0;
                        } else {
                            batch.inv.push({ id: m.inventory.id, qty: m.inventory.quantity.value });
                            batch.rqd[componentId] -= m.inventory.quantity.value;
                            m.inventory.quantity.value = 0;
                        }
                    }
                }
            });
        });
    });

    // Determine whether all requirements are fulfilled
    let result = output.every(batch => Object.values(batch.rqd).every(v => v <= 0));

    // Accumulate additional requirements if needed
    let reqd = {};
    if (!result) {
        reqd = bom.reduce((acc, b) => {
            const componentId = buildId(b.componentProductStrategyProcessId, b.componentProduct.id, b.workOrderProcessId);
            acc[componentId] = { code: b.componentProduct.code, qty: 0 };
            return acc;
        }, {});

        output.forEach((batch) => {
            Object.keys(batch.rqd).forEach((key) => {
                reqd[key].qty += batch.rqd[key];
            });
        });
    }

    return { material, output, result, reqd };
}

// Execute the main function with contextual data
const { material, output, result, reqd } = getMaterialRequirements(
    $state.context.LOCAL.material,
    $state.context.LOCAL.quantity,
    $state.context.LOCAL.standardPack,
    $state.context.LOCAL.allBoms,
    $state.context.LOCAL?.partial?.map(p => ({ id: p.id, qty: p.quantity.value })) || [],
    $state.context.LOCAL.wip?.id || "!!!",
    $state.context.REQUEST.DATA?.components || {}
);

return { material, output, result, reqd };

