					)
			],
			[
				$components[isLabor]
					.{
						"update": {
							"quantity": 0,
							"totalSetupHours": $coalesce([totalSetupHours, 0])
								+ $coalesce([$productionHistory.actualSetupHours, 0]),
							"totalLaborHours": $coalesce([totalLaborHours, 0])
								+ $coalesce([$productionHistory.actualLaborHours, 0]),
							"totalOverheadHours": $coalesce([totalOverheadHours, 0])
								+ $coalesce([$productionHistory.actualMachineHours, 0])
						},
						"where": { "id": id }
					}
			]
		),
		"it": $inventoryTransaction
			.{
				"update": {
					"aggregationId": $productionAggregation.id & "-" & sourceProductId
				},
				"where": { "id": id }
			},
		"h": {
			"update": { "aggregationId": $productionAggregation.id },
			"where": { "id": $productionHistory.id }
		}
	} 
)
